api.post('/questions',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=parse(z.object({categoryId:z.string().uuid().optional(),questionText:z.string().trim().min(1).max(3000),questionType:z.enum(['single_choice','multiple_choice','true_false']).default('single_choice'),difficulty:z.enum(['easy','medium','hard']).default('medium'),options:z.array(z.object({text:z.string().trim().min(1).max(1000)})).length(4),correctIndexes:z.array(z.number().int()).length(1),status:z.enum(['draft','published']).default('draft'),explanation:z.string().trim().max(3000).default(''),sourceDocument:z.string().trim().max(500).nullable().optional(),sourceRevision:z.string().trim().max(200).nullable().optional(),sourceSection:z.string().trim().max(200).nullable().optional(),sourceLocation:z.string().trim().max(200).nullable().optional(),changeReason:z.string().trim().max(1000).optional(),duplicateOverride:z.object({reason:z.string().trim().min(10).max(500)}).optional()}),req.body);if(!p.success)return fail(res,400,'VALIDATION','Асуултын талбаруудыг шалгана уу.');const validation=validateQuestionDraft(p.data);if(validation)return fail(res,400,'VALIDATION',validation);if(p.data.correctIndexes.length!==1)return fail(res,400,'VALIDATION','Яг нэг зөв хариултыг сонгоно уу.');const categoryId=p.data.categoryId??(await db.select({id:s.categories.id}).from(s.categories).where(eq(s.categories.isActive,true)).orderBy(asc(s.categories.name)).limit(1))[0]?.id;if(!categoryId)return fail(res,400,'VALIDATION','Идэвхтэй ангилал олдсонгүй.');const category=await db.select({id:s.categories.id}).from(s.categories).where(and(eq(s.categories.id,categoryId),eq(s.categories.isActive,true))).limit(1);if(!category.length)return fail(res,400,'VALIDATION','Идэвхтэй ангилал сонгоно уу.');const existing=await db.select({id:s.questions.id,questionText:s.questions.questionText,status:s.questions.status}).from(s.questions).where(inArray(s.questions.status,['draft','pending_review','approved','published']));const matches=existing.map(item=>({...item,similarity:questionSimilarity(item.questionText,p.data.questionText)})).filter(item=>item.similarity>=0.82).sort((a,b)=>b.similarity-a.similarity).slice(0,5);const result=await db.transaction(async tx=>{const[q]=await tx.insert(s.questions).values({categoryId,status:p.data.status,questionText:p.data.questionText,questionType:p.data.questionType,difficulty:p.data.difficulty,explanation:p.data.explanation,createdBy:req.user!.id,sourceDocument:p.data.sourceDocument??null,sourceRevision:p.data.sourceRevision??null,sourceSection:p.data.sourceSection??null,sourceLocation:p.data.sourceLocation??null}).returning();const opts=await tx.insert(s.questionOptions).values(p.data.options.map((x:{text:string},i:number)=>({questionId:q.id,optionText:x.text,optionOrder:i}))).returning();await tx.insert(s.questionCorrectOptions).values(p.data.correctIndexes.map((i:number)=>({questionId:q.id,optionId:opts[i].id})));await tx.insert(s.questionRevisions).values({questionId:q.id,revisionNumber:1,previousData:{questionText:q.questionText,options:p.data.options,sourceDocument:q.sourceDocument,sourceRevision:q.sourceRevision,sourceSection:q.sourceSection,sourceLocation:q.sourceLocation},changedBy:req.user!.id,changeReason:p.data.changeReason||'Анхны хувилбар'});await tx.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'question.created',entityType:'question',entityId:q.id,metadata:{status:q.status,duplicateOverride:p.data.duplicateOverride?.reason??null,possibleDuplicateIds:matches.map(match=>match.id)}});return q});res.status(201).json({question:{id:result.id,status:result.status,questionText:result.questionText},possibleDuplicates:matches})}catch(e){next(e)}});
