api.post('/questions/bulk-approve',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=bulkReviewBody.safeParse(req.body);if(!p.success)return fail(res,400,'REVIEW_NOTE','Хяналтын хүсэлтийн мэдээллийг шалгана уу.');const result=await db.transaction(async tx=>{const approved:string[]=[],blocked:{id:string;questionText?:string;reasons:string[]}[]=[];for(const item of [...p.data.items].sort((a,b)=>a.questionId.localeCompare(b.questionId))){const id=item.questionId;await tx.execute(sql`select id from questions where id=${id} for update`);const[q]=await tx.select().from(s.questions).where(eq(s.questions.id,id)).limit(1);if(!q){blocked.push({id,reasons:['Асуулт олдсонгүй.']});continue}const options=await tx.select({id:s.questionOptions.id,text:s.questionOptions.optionText}).from(s.questionOptions).where(eq(s.questionOptions.questionId,id)).orderBy(asc(s.questionOptions.optionOrder));const correct=await tx.select({optionId:s.questionCorrectOptions.optionId}).from(s.questionCorrectOptions).where(eq(s.questionCorrectOptions.questionId,id));const reasons=questionReviewReasons({status:q.status,questionText:q.questionText,questionType:q.questionType,explanation:q.explanation,sourceDocument:q.sourceDocument,sourceRevision:q.sourceRevision,sourceSection:q.sourceSection,sourceLocation:q.sourceLocation,options:options.map(option=>({text:option.text})),correctIndexes:options.map((option,index)=>correct.some(answer=>answer.optionId===option.id)?index:-1).filter(index=>index>=0)});if(reasons.length){blocked.push({id,questionText:q.questionText,reasons});continue}const now=new Date();const[updated]=await tx.update(s.questions).set({status:'approved',reviewedBy:req.user!.id,approvedAt:now,lastReviewedAt:now,updatedAt:now}).where(and(eq(s.questions.id,id),eq(s.questions.status,'pending_review'))).returning({id:s.questions.id});if(!updated){blocked.push({id,questionText:q.questionText,reasons:['Асуултын төлөв зэрэгцээ өөрчлөгдсөн; дахин ачаалж шалгана уу.']});continue}await tx.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'question.approved',entityType:'question',entityId:id,metadata:{verificationNote:normalizeReviewNote(item.verificationNote),bulk:true}});approved.push(id)}return{approved,blocked}});res.json({approvedCount:result.approved.length,approvedIds:result.approved,blockedCount:result.blocked.length,blocked:result.blocked})}catch(e){next(e)}});
api.post('/questions/:id/publish',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=singleQuestionPublishRequest.safeParse(req.body??{});if(!p.success)return fail(res,400,'VALIDATION','Нийтлэх хүсэлтийн мэдээллийг шалгана уу.');const id=String(req.params.id),result=await db.transaction(async tx=>{const[q]=await tx.select().from(s.questions).where(eq(s.questions.id,id)).for('update').limit(1);if(!q)return'not_found' as const;if(q.status==='archived'||q.status==='published')return'workflow' as const;const optionRows=await tx.select({id:s.questionOptions.id,optionText:s.questionOptions.optionText}).from(s.questionOptions).where(eq(s.questionOptions.questionId,id)).orderBy(asc(s.questionOptions.optionOrder));const correctRows=await tx.select({optionId:s.questionCorrectOptions.optionId}).from(s.questionCorrectOptions).where(eq(s.questionCorrectOptions.questionId,id));const incomplete=validateQuestionDraft({questionText:q.questionText,questionType:q.questionType,options:optionRows.map(row=>({text:row.optionText})),correctIndexes:optionRows.map((row,index)=>correctRows.some(correct=>correct.optionId===row.id)?index:-1).filter(index=>index>=0)});if(incomplete||optionRows.length!==4||correctRows.length!==1)return'incomplete' as const;const now=new Date();await tx.update(s.questions).set({status:'published',updatedAt:now}).where(eq(s.questions.id,id));const links=await tx.select({quizId:s.quizQuestions.quizId}).from(s.quizQuestions).where(eq(s.quizQuestions.questionId,id));for(const link of links){const[count]=await tx.select({count:sql<number>`count(*)::int`}).from(s.quizQuestions).innerJoin(s.questions,eq(s.questions.id,s.quizQuestions.questionId)).where(and(eq(s.quizQuestions.quizId,link.quizId),eq(s.questions.status,'published')));await tx.update(s.quizzes).set({questionCount:count.count,updatedAt:now}).where(eq(s.quizzes.id,link.quizId));}await tx.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'question.published',entityType:'question',entityId:id,metadata:{sourceDocument:q.sourceDocument,sourceRevision:q.sourceRevision,sourceSection:q.sourceSection,sourceLocation:q.sourceLocation,verificationNote:normalizeReviewNote(p.data.verificationNote)}});return'published' as const});if(result==='not_found')return fail(res,404,'NOT_FOUND','Асуулт олдсонгүй.');if(result==='workflow')return fail(res,409,'WORKFLOW','Архивласан эсвэл өмнө нийтэлсэн асуултыг энэ үйлдлээр нийтлэхгүй.');if(result==='incomplete')return fail(res,409,'QUESTION_INCOMPLETE','Нийтлэхээс өмнө асуултын текст, сонголт, зөв хариултыг шалгана уу.');res.json({status:'published'})}catch(e){next(e)}});
const bulkQuestionIds=z.array(z.string().uuid()).min(1).max(100).refine(ids=>new Set(ids).size===ids.length);
async function readBulkQuestion(tx:any,id:string):Promise<BulkQuestionInput|null>{const[q]=await tx.select().from(s.questions).where(eq(s.questions.id,id)).limit(1);if(!q)return null;const options=await tx.select({id:s.questionOptions.id,text:s.questionOptions.optionText}).from(s.questionOptions).where(eq(s.questionOptions.questionId,id)).orderBy(asc(s.questionOptions.optionOrder));const correct=await tx.select({optionId:s.questionCorrectOptions.optionId}).from(s.questionCorrectOptions).where(eq(s.questionCorrectOptions.questionId,id));return{id,status:q.status,questionText:q.questionText,questionType:q.questionType,explanation:q.explanation,sourceDocument:q.sourceDocument,sourceRevision:q.sourceRevision,sourceSection:q.sourceSection,sourceLocation:q.sourceLocation,options,correctOptionIds:correct.map((row:{optionId:string})=>row.optionId)}}
api.post('/questions/bulk-publish/preview',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=parse(z.object({questionIds:bulkQuestionIds}),req.body);if(!p.success)return fail(res,400,'VALIDATION','Нийтлэх асуултын жагсаалтыг шалгана уу.');const items=[];for(const id of p.data.questionIds){const question=await readBulkQuestion(db,id);const reasons=question?questionPublishReasons(question):['Асуулт олдсонгүй.'];items.push({id,questionText:question?.questionText,status:question?.status,sourceDocument:question?.sourceDocument,sourceRevision:question?.sourceRevision,sourceSection:question?.sourceSection,sourceLocation:question?.sourceLocation,ready:!reasons.length,reasons});}res.json({total:items.length,readyCount:items.filter(item=>item.ready).length,blockedCount:items.filter(item=>!item.ready).length,items})}catch(e){next(e)}});
const bulkPublishBody=bulkQuestionPublishRequest;
api.post('/questions/bulk-publish',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=bulkPublishBody.safeParse(req.body);if(!p.success)return fail(res,400,'VALIDATION','Нийтлэх хүсэлтийн мэдээллийг шалгана уу.');const notes=new Map<string,string|null>(p.data.items.map(item=>[item.questionId,normalizeReviewNote(item.verificationNote)]));const result=await db.transaction(async tx=>{const published:string[]=[],blocked:{id:string;reasons:string[]}[]=[];for(const id of [...notes.keys()].sort()){await tx.execute(sql`select id from questions where id=${id} for update`);const question=await readBulkQuestion(tx,id);const reasons=question?questionPublishReasons(question):['Асуулт олдсонгүй.'];if(reasons.length){blocked.push({id,reasons});continue;}const now=new Date();await tx.update(s.questions).set({status:'published',updatedAt:now}).where(and(eq(s.questions.id,id),eq(s.questions.status,question!.status as 'published'|'archived'|'draft'|'pending_review'|'approved'|'rejected')));const links=await tx.select({quizId:s.quizQuestions.quizId}).from(s.quizQuestions).where(eq(s.quizQuestions.questionId,id));for(const link of links){const[count]=await tx.select({count:sql<number>`count(*)::int`}).from(s.quizQuestions).innerJoin(s.questions,eq(s.questions.id,s.quizQuestions.questionId)).where(and(eq(s.quizQuestions.quizId,link.quizId),eq(s.questions.status,'published')));await tx.update(s.quizzes).set({questionCount:count.count,updatedAt:now}).where(eq(s.quizzes.id,link.quizId));}await tx.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'question.published',entityType:'question',entityId:id,metadata:{sourceDocument:question!.sourceDocument,sourceRevision:question!.sourceRevision,sourceSection:question!.sourceSection,sourceLocation:question!.sourceLocation,verificationNote:notes.get(id)??null,bulk:true}});published.push(id);}return{published,blocked}});res.json({publishedCount:result.published.length,publishedIds:result.published,blockedCount:result.blocked.length,blocked:result.blocked})}catch(e){next(e)}});
api.post('/quizzes',requireAuth,requireRoles('admin','training_manager'),async(req,res,next)=>{try{const p=parse(z.object({title:z.string().trim().min(3).max(200),description:z.string().max(2000).nullable().optional(),categoryId:z.string().uuid().optional(),questionIds:z.array(z.string().uuid()).min(1).max(100),timeLimitSeconds:z.number().int().positive().max(86400).nullable().optional(),passingPercentage:z.number().int().min(0).max(100).default(70),attemptsAllowed:z.number().int().min(0).max(20).default(1),isTest:z.boolean().default(false),showExplanations:z.boolean().default(true),pointsPerQuestion:z.number().int().min(1).max(1000).default(100)}).superRefine((value,context)=>{if(value.attemptsAllowed===0&&!value.isTest)context.addIssue({code:z.ZodIssueCode.custom,path:['attemptsAllowed'],message:'Хязгааргүй оролдлого зөвхөн туршилтын сорилд боломжтой.'})}),req.body);if(!p.success)return fail(res,400,'VALIDATION','Сорилын мэдээллийг шалгана уу.');if(p.data.isTest&&req.user!.role!=='admin')return fail(res,403,'FORBIDDEN','Туршилтын сорилын тохиргоог зөвхөн админ удирдана.');if(new Set(p.data.questionIds).size!==p.data.questionIds.length)return fail(res,400,'VALIDATION','Нэг асуултыг давхар оруулах боломжгүй.');const result=await db.transaction(async tx=>{const approved=await tx.select({id:s.questions.id}).from(s.questions).where(and(inArray(s.questions.id,p.data.questionIds),eq(s.questions.status,'published')));if(approved.length!==p.data.questionIds.length)throw Object.assign(new Error('Зөвхөн нийтэлсэн асуултыг сорилд оруулна.'),{status:400});const[q]=await tx.insert(s.quizzes).values({title:p.data.title,description:p.data.description,categoryId:p.data.categoryId,questionCount:p.data.questionIds.length,timeLimitSeconds:p.data.timeLimitSeconds,passingPercentage:p.data.passingPercentage,attemptsAllowed:p.data.attemptsAllowed,isTest:p.data.isTest,showExplanations:p.data.showExplanations,createdBy:req.user!.id,status:'draft'}).returning();await tx.insert(s.quizQuestions).values(p.data.questionIds.map((questionId:string,i:number)=>({quizId:q.id,questionId,questionOrder:i,points:p.data.pointsPerQuestion})));await tx.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'quiz.created',entityType:'quiz',entityId:q.id});return q});res.status(201).json({quiz:{id:result.id,status:result.status,title:result.title}})}catch(e){next(e)}});
