api.get('/teams',requireAuth,async(req,res,next)=>{try{if(req.user!.role==='admin'){const items=await db.select().from(s.teams).where(eq(s.teams.isActive,true)).orderBy(asc(s.teams.name));return res.json({items})}const items=await db.select({id:s.teams.id,name:s.teams.name,description:s.teams.description,isActive:s.teams.isActive}).from(s.teamMembers).innerJoin(s.teams,eq(s.teams.id,s.teamMembers.teamId)).where(and(eq(s.teamMembers.userId,req.user!.id),sql`${s.teamMembers.leftAt} is null`,eq(s.teams.isActive,true)));res.json({items})}catch(e){next(e)}});
api.post('/teams',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=parse(z.object({name:z.string().trim().min(2).max(160),description:z.string().max(1000).optional()}),req.body);if(!p.success)return fail(res,400,'VALIDATION','Багийн мэдээлэл буруу байна.');const[t]=await db.insert(s.teams).values(p.data).returning();await db.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'team.created',entityType:'team',entityId:t.id});res.status(201).json({team:t})}catch(e){next(e)}});
api.get('/teams/:id/members',requireAuth,async(req,res,next)=>{try{const id=String(req.params.id);if(req.user!.role!=='admin'){const own=await db.select().from(s.teamMembers).where(and(eq(s.teamMembers.teamId,id),eq(s.teamMembers.userId,req.user!.id),sql`${s.teamMembers.leftAt} is null`));if(!own.length)return fail(res,403,'FORBIDDEN','Энэ багийн мэдээллийг харах эрхгүй.')}const items=await db.select({id:s.users.id,username:s.users.username,fullName:s.users.fullName,role:s.users.role,joinedAt:s.teamMembers.joinedAt}).from(s.teamMembers).innerJoin(s.users,eq(s.users.id,s.teamMembers.userId)).where(and(eq(s.teamMembers.teamId,id),sql`${s.teamMembers.leftAt} is null`)).orderBy(asc(s.users.fullName));res.json({items})}catch(e){next(e)}});
api.post('/teams/:id/members',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=parse(z.object({userId:z.string().uuid()}),req.body);if(!p.success)return fail(res,400,'VALIDATION','Хэрэглэгчийн ID буруу байна.');const id=String(req.params.id),[team]=await db.select().from(s.teams).where(and(eq(s.teams.id,id),eq(s.teams.isActive,true)));if(!team)return fail(res,404,'NOT_FOUND','Баг олдсонгүй.');const active=await db.select().from(s.teamMembers).where(and(eq(s.teamMembers.userId,p.data.userId),sql`${s.teamMembers.leftAt} is null`));if(active.length)return fail(res,409,'ACTIVE_MEMBERSHIP','Хэрэглэгч аль хэдийн идэвхтэй багт байна.');const[m]=await db.insert(s.teamMembers).values({teamId:id,userId:p.data.userId}).returning();await db.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'team.member_added',entityType:'team',entityId:id,metadata:{userId:p.data.userId}});res.status(201).json({membership:m})}catch(e){next(e)}});
api.delete('/teams/:id/members/:userId',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const id=String(req.params.id),userId=String(req.params.userId),[m]=await db.update(s.teamMembers).set({leftAt:new Date()}).where(and(eq(s.teamMembers.teamId,id),eq(s.teamMembers.userId,userId),sql`${s.teamMembers.leftAt} is null`)).returning();if(!m)return fail(res,404,'NOT_FOUND','Идэвхтэй гишүүн олдсонгүй.');await db.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'team.member_removed',entityType:'team',entityId:id,metadata:{userId}});res.status(204).end()}catch(e){next(e)}});
api.get('/competitions',requireAuth,async(_req,res,next)=>{try{const items=await db.select({id:s.competitions.id,quizId:s.competitions.quizId,title:s.competitions.title,description:s.competitions.description,startsAt:s.competitions.startsAt,endsAt:s.competitions.endsAt,status:s.competitions.status,attemptsAllowed:s.competitions.attemptsAllowed}).from(s.competitions).where(sql`${s.competitions.status} in ('scheduled','active','completed')`).orderBy(asc(s.competitions.startsAt));res.json({items})}catch(e){next(e)}});
api.post('/competitions',requireAuth,requireRoles('admin'),async(req,res,next)=>{try{const p=parse(z.object({quizId:z.string().uuid(),title:z.string().trim().min(3).max(200),description:z.string().max(2000).optional(),startsAt:z.coerce.date(),endsAt:z.coerce.date(),teamIds:z.array(z.string().uuid()).default([]),attemptsAllowed:z.number().int().min(1).max(20).default(1)}),req.body);if(!p.success||p.data.endsAt<=p.data.startsAt||p.data.endsAt<=new Date())return fail(res,400,'VALIDATION','Уралдааны хугацаа болон мэдээллийг шалгана уу.');const[q]=await db.select().from(s.quizzes).where(and(eq(s.quizzes.id,p.data.quizId),eq(s.quizzes.status,'published')));if(!q)return fail(res,400,'QUIZ_NOT_PUBLISHED','Уралдаанд зөвхөн нийтэлсэн сорил холбоно.');const c=await db.transaction(async tx=>{const[created]=await tx.insert(s.competitions).values({quizId:q.id,title:p.data.title,description:p.data.description,startsAt:p.data.startsAt,endsAt:p.data.endsAt,status:p.data.startsAt>new Date()?'scheduled':'active',attemptsAllowed:p.data.attemptsAllowed,scoringConfig:q.scoringConfig,createdBy:req.user!.id}).returning();if(p.data.teamIds.length)await tx.insert(s.competitionTeams).values(p.data.teamIds.map((teamId:string)=>({competitionId:created.id,teamId})));await tx.insert(s.auditLogs).values({actorUserId:req.user!.id,action:'competition.created',entityType:'competition',entityId:created.id,metadata:{tieBreak:['score','accuracy','elapsed_time']}});return created});res.status(201).json({competition:c,tieBreak:['final_score','accuracy','shorter_completion_time']})}catch(e){next(e)}});
api.post('/competitions/:id/register',requireAuth,async(req,res,next)=>{try{const id=String(req.params.id),[c]=await db.select().from(s.competitions).where(eq(s.competitions.id,id));if(!c)return fail(res,404,'NOT_FOUND','Уралдаан олдсонгүй.');const now=new Date();if(now>c.endsAt||!['scheduled','active'].includes(c.status))return fail(res,409,'DEADLINE','Уралдааны хугацаа дууссан.');const restricted=await db.select().from(s.competitionTeams).where(eq(s.competitionTeams.competitionId,id));if(restricted.length){const memberships=await db.select().from(s.teamMembers).where(and(eq(s.teamMembers.userId,req.user!.id),sql`${s.teamMembers.leftAt} is null`));if(!memberships.some(m=>restricted.some(t=>t.teamId===m.teamId)))return fail(res,403,'NOT_ELIGIBLE','Энэ баг уралдаанд оролцох эрхгүй.')}await db.insert(s.competitionParticipants).values({competitionId:id,userId:req.user!.id}).onConflictDoNothing();res.status(201).json({registered:true,startsAt:c.startsAt,endsAt:c.endsAt})}catch(e){next(e)}});
api.get('/competitions/:id/leaderboard',requireAuth,async(req,res,next)=>{try{const id=String(req.params.id),[competition]=await db.select().from(s.competitions).where(eq(s.competitions.id,id));if(!competition)return fail(res,404,'NOT_FOUND','Уралдаан олдсонгүй.');if(competition.status!=='completed'&&req.user!.role!=='admin'){const mine=await db.select().from(s.competitionParticipants).where(and(eq(s.competitionParticipants.competitionId,id),eq(s.competitionParticipants.userId,req.user!.id)));if(!mine.length)return fail(res,403,'FORBIDDEN','Уралдааны үр дүнг харах эрхгүй.')}const attempts=await db.select({userId:s.quizAttempts.userId,fullName:s.users.fullName,score:s.quizAttempts.score,accuracy:s.quizAttempts.accuracy,time:s.quizAttempts.elapsedSeconds,startedAt:s.quizAttempts.startedAt}).from(s.quizAttempts).innerJoin(s.users,eq(s.users.id,s.quizAttempts.userId)).where(and(eq(s.quizAttempts.competitionId,id),eq(s.quizAttempts.status,'submitted'))).orderBy(desc(s.quizAttempts.score),desc(s.quizAttempts.accuracy),asc(s.quizAttempts.elapsedSeconds));const best=rankAttempts(attempts),individual=best.map((a,i)=>({...a,rank:i+1}));const eligibleTeams=await db.select({teamId:s.competitionTeams.teamId,name:s.teams.name}).from(s.competitionTeams).innerJoin(s.teams,eq(s.teams.id,s.competitionTeams.teamId)).where(eq(s.competitionTeams.competitionId,id));const teams=await Promise.all(eligibleTeams.map(async team=>{const roster=await db.select().from(s.teamMembers).where(eq(s.teamMembers.teamId,team.teamId));const started=best.filter(a=>roster.some(m=>m.userId===a.userId&&m.joinedAt<=a.startedAt&&(!m.leftAt||m.leftAt>a.startedAt)));const avg=averageScore(started.map(a=>a.score));return{id:team.teamId,name:team.name,participants:started.length,averageScore:avg}}));teams.sort((a,b)=>b.averageScore-a.averageScore);res.json({individual,teams,tieBreak:['final_score','accuracy','shorter_completion_time']})}catch(e){next(e)}});
api.get('/reports/individual',requireAuth,requireRoles('admin','training_manager'),async(req,res,next)=>{try{const p=parse(z.object({page:z.coerce.number().int().min(1).default(1),limit:z.coerce.number().int().min(1).max(100).default(25)}),req.query);if(!p.success)return fail(res,400,'VALIDATION','Хуудасны дугаар буруу байна.');const items=await db.select({userId:s.users.id,username:s.users.username,fullName:s.users.fullName,quizTitle:s.quizzes.title,score:s.quizAttempts.score,accuracy:s.quizAttempts.accuracy,correctCount:s.quizAttempts.correctCount,incorrectCount:s.quizAttempts.incorrectCount,submittedAt:s.quizAttempts.submittedAt}).from(s.quizAttempts).innerJoin(s.users,eq(s.users.id,s.quizAttempts.userId)).innerJoin(s.quizzes,eq(s.quizzes.id,s.quizAttempts.quizId)).where(eq(s.quizAttempts.status,'submitted')).orderBy(desc(s.quizAttempts.submittedAt)).limit(p.data.limit).offset((p.data.page-1)*p.data.limit);res.json({items,page:p.data.page,limit:p.data.limit})}catch(e){next(e)}});
api.get('/reports/teams',requireAuth,requireRoles('admin','training_manager'),async(_req,res,next)=>{try{const items=await db.select({teamId:s.teams.id,teamName:s.teams.name,userId:s.users.id,fullName:s.users.fullName,score:s.quizAttempts.score,accuracy:s.quizAttempts.accuracy,submittedAt:s.quizAttempts.submittedAt}).from(s.teamMembers).innerJoin(s.teams,eq(s.teams.id,s.teamMembers.teamId)).innerJoin(s.users,eq(s.users.id,s.teamMembers.userId)).innerJoin(s.quizAttempts,eq(s.quizAttempts.userId,s.users.id)).where(eq(s.quizAttempts.status,'submitted')).orderBy(asc(s.teams.name),desc(s.quizAttempts.score));res.json({items})}catch(e){next(e)}});
api.get('/reports/topics',requireAuth,requireRoles('admin','training_manager'),async(_req,res,next)=>{try{const items=await db.select({categoryId:s.categories.id,category:s.categories.name,total:sql<number>`count(*)::int`,correct:sql<number>`count(*) filter (where ${s.answers.isCorrect}=true)::int`,accuracy:sql<number>`coalesce(avg(case when ${s.answers.isCorrect}=true then 100.0 else 0.0 end),0)::float`}).from(s.answers).innerJoin(s.questions,eq(s.questions.id,s.answers.questionId)).innerJoin(s.categories,eq(s.categories.id,s.questions.categoryId)).innerJoin(s.quizAttempts,eq(s.quizAttempts.id,s.answers.attemptId)).where(eq(s.quizAttempts.status,'submitted')).groupBy(s.categories.id,s.categories.name).orderBy(asc(s.categories.sortOrder));res.json({items})}catch(e){next(e)}});
api.get('/reports/export',requireAuth,requireRoles('admin'),async(_req,res,next)=>{try{const rows=await db.select({username:s.users.username,fullName:s.users.fullName,quiz:s.quizzes.title,score:s.quizAttempts.score,accuracy:s.quizAttempts.accuracy,correct:s.quizAttempts.correctCount,incorrect:s.quizAttempts.incorrectCount,submittedAt:s.quizAttempts.submittedAt}).from(s.quizAttempts).innerJoin(s.users,eq(s.users.id,s.quizAttempts.userId)).innerJoin(s.quizzes,eq(s.quizzes.id,s.quizAttempts.quizId)).where(eq(s.quizAttempts.status,'submitted')).orderBy(desc(s.quizAttempts.submittedAt));const cell=(value:unknown)=>{const raw=String(value??'');const safe=/^[=+@-]/.test(raw)?"'"+raw:raw;return'"'+safe.replace(/"/g,'""')+'"'};const csv=['Нэвтрэх нэр,Овог нэр,Сорил,Оноо,Нарийвчлал,Зөв,Буруу,Илгээсэн',...rows.map(r=>[r.username,r.fullName,r.quiz,r.score,r.accuracy,r.correct,r.incorrect,r.submittedAt?.toISOString()].map(cell).join(','))].join('\r\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="unit111-results.csv"');res.send('\ufeff'+csv)}catch(e){next(e)}});
api.get('/audit-logs',requireAuth,requireRoles('admin'),async(_req,res,next)=>{try{const items=await db.select().from(s.auditLogs).orderBy(desc(s.auditLogs.createdAt)).limit(200);res.json({items})}catch(e){next(e)}});
api.use(adminContentRouter);api.use(courseManagementRouter);api.use('/learning',learningRouter);api.use((_req,res,_next)=>fail(res,404,'NOT_FOUND','Хүссэн мэдээлэл олдсонгүй.'));app.use((err:unknown,req:express.Request,res:express.Response,_next:express.NextFunction)=>{const e=err as {status?:number;code?:string;message?:string};if(!e.status)console.error('API request failed',{method:req.method,path:req.path,code:e.code||'UNEXPECTED'});if(e.code==='42703'||e.code==='42P01')return fail(res,503,'SCHEMA_OUTDATED','Өгөгдлийн сангийн schema кодын хувилбараас хоцорсон байна. Локал database migration-уудыг шалгана уу.');res.status(e.status||500).json({error:{code:e.status?'REQUEST_FAILED':'INTERNAL',message:e.status?e.message:'Серверийн алдаа гарлаа.'}})});export {app};if(process.env.UNIT111_API_NO_LISTEN!=='1')app.listen(port,'0.0.0.0',()=>console.log(`Unit111 API :${port}`));


















